package dicecore

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"testing"
)

type pathfinder2eParityCase struct {
	Name          string
	System        string
	Input         any
	Options       SystemRollOptions
	Outcome       json.RawMessage
	EngineResult  *DiceRollResult
	EngineDetails *DiceRollDetails
}

// This fixture is generated by the TypeScript implementation, never the Go
// port. It verifies complete JSON and stable errors with both shared RNGs.
func TestPathfinder2eTypeScriptParity(t *testing.T) {
	data, err := os.ReadFile("testdata/pathfinder2e-parity.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		SchemaVersion int
		Cases         []pathfinder2eParityCase
		Contracts     []pathfinder2eParityCase
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if fixture.SchemaVersion != 1 || len(fixture.Cases) == 0 || len(fixture.Contracts) == 0 {
		t.Fatal("empty or invalid TypeScript parity fixture")
	}
	for _, c := range fixture.Cases {
		t.Run(c.Name, func(t *testing.T) {
			var value any
			var err error
			if c.System == "mixed" {
				value, err = RollMixedDice(c.Input, c.Options)
			} else {
				value, err = RollPathfinder2e(c.Input, c.Options)
			}
			assertPathfinder2eParity(t, c.Outcome, value, err)
		})
	}
	for _, c := range fixture.Contracts {
		t.Run(c.Name, func(t *testing.T) {
			engine := &pathfinder2eFixtureEngine{Engine: DefaultDiceEngine(), result: c.EngineResult, details: c.EngineDetails}
			value, err := RollPathfinder2eWithEngine(engine, c.Input, c.Options)
			assertPathfinder2eParity(t, c.Outcome, value, err)
		})
	}
}

func assertPathfinder2eParity(t *testing.T, expected json.RawMessage, value any, err error) {
	t.Helper()
	var outcome struct {
		Value json.RawMessage
		Error map[string]any
	}
	if err := json.Unmarshal(expected, &outcome); err != nil {
		t.Fatal(err)
	}
	if outcome.Error != nil {
		if err == nil {
			t.Fatalf("expected error %s, got %+v", expected, value)
		}
		actual := map[string]any{"message": err.Error()}
		var diceErr *DiceRollError
		if errors.As(err, &diceErr) {
			data, err := json.Marshal(diceErr)
			if err != nil {
				t.Fatal(err)
			}
			if err := json.Unmarshal(data, &actual); err != nil {
				t.Fatal(err)
			}
		}
		for field, wanted := range outcome.Error {
			if field == "name" && diceErr == nil {
				continue // Native Go errors have no JavaScript constructor name.
			}
			if !reflect.DeepEqual(actual[field], wanted) {
				t.Errorf("error %s: got %#v, want %#v", field, actual[field], wanted)
			}
		}
		return
	}
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	actualData, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	var actual, wanted any
	if err := json.Unmarshal(actualData, &actual); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(outcome.Value, &wanted); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(actual, wanted) {
		t.Errorf("Go/TypeScript JSON differs\ngot %s\nwant %s", actualData, outcome.Value)
	}
}
